(() => {
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const statuses={all:'Todos',pendente:'Pendente',pago:'Pago',a_caminho:'A caminho',entregue:'Entregue',expirado:'Expirado',cancelado:'Cancelado',reembolsado:'Reembolsado'};
let active='all',query='';
function orders(){try{const demo=JSON.parse(sessionStorage.getItem('local-orders')||'[]');const rows=[...(Array.isArray(demo)?demo:[]),...(window.paymentUI?.saved()||[])];return Array.isArray(rows)?rows.filter(o=>o&&typeof o.id==='string'&&Array.isArray(o.items)).slice().sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt)):[]}catch{return []}}
function profile(){try{return JSON.parse(localStorage.getItem('selected-roblox-profile'))||{}}catch{return {}}}
function avatar(p){try{const u=new URL(p.avatarUrl);if(u.protocol==='https:'&&(u.hostname==='rbxcdn.com'||u.hostname.endsWith('.rbxcdn.com')))return '<img src="'+esc(u.href)+'" alt="Seu avatar Roblox" referrerpolicy="no-referrer">'}catch{}return '<span aria-hidden="true">♙</span>'}
function results(){const all=orders(),rows=all.filter(o=>(active==='all'||o.status===active)&&(o.id+' '+o.items.map(i=>i.name).join(' ')).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')));if(!rows.length)return '<div class="orders-empty"><span class="orders-empty-icon">'+bag+'</span><h2>'+(all.length?'Nenhum pedido encontrado.':'Você ainda não fez nenhum pedido.')+'</h2><p>'+(all.length?'Experimente outro produto, ID ou filtro.':'Quando concluir uma compra nesta versão, seu pedido aparecerá aqui.')+'</p><div><a class="button" href="/robux">Comprar Robux ›</a><a class="orders-secondary" href="/loja">Ver loja</a></div></div>';return '<div class="orders-list">'+rows.map(o=>'<article class="order-card"><div class="order-card-head"><div><small>PEDIDO</small><h2>'+esc(o.id)+'</h2><time>'+esc(new Date(o.createdAt).toLocaleString('pt-BR'))+'</time></div><span class="order-status">'+esc(o.environment==='sandbox'?'Teste · '+(statuses[o.status]||o.status):o.status==='demonstracao'?'Demonstração':statuses[o.status]||'Status indisponível')+'</span></div><ul>'+o.items.map(i=>'<li><span>'+esc(i.name)+'<small>'+esc(i.qty)+' unidade(s) × '+money(i.price)+'</small></span><strong>'+money(Math.round(i.price*100)*i.qty/100)+'</strong></li>').join('')+'</ul><div class="order-card-foot"><span>Conta Roblox <b>@'+esc(o.robloxUsername)+'</b></span><strong>'+money(o.total)+'</strong></div><details><summary>Ver detalhes do pedido</summary><p>E-mail: '+esc(o.email)+'</p><p>'+(o.paymentId?'Pagamento via PurinCash · '+esc(o.paymentId)+'. A entrega dos itens é acompanhada separadamente.':'Pedido local de demonstração. Nenhum pagamento ou entrega real foi realizado.')+'</p></details>'+(o.paymentId&&(o.status==='pendente'||o.status==='pago')?'<button class="pc-resume" data-pc-resume="'+esc(o.id)+'">Ver PIX / consultar pagamento</button>':'')+'</article>').join('')+'</div>'}
const bag='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M4 7h16v14H4zM4 7l3-4h10l3 4M8 10a4 4 0 0 0 8 0"/></svg>';
function page(){active='all';query='';const p=profile();return '<section class="orders-page wrap">'+window.accountUI.sidebar(p,'orders')+'<div class="orders-content"><div class="orders-heading"><div><h1>Meus Pedidos</h1><p>Acompanhe suas compras, entregas e status.</p></div><label class="orders-search"><span aria-hidden="true">⌕</span><input id="orders-search" type="search" aria-label="Buscar por produto ou ID" placeholder="Buscar por produto ou ID…"></label></div><div class="orders-filters" role="group" aria-label="Filtrar pedidos por status">'+Object.entries(statuses).map(([k,v])=>'<button data-order-filter="'+k+'" aria-pressed="'+(k==='all')+'">'+v+'</button>').join('')+'</div><p class="orders-local-note">Histórico deste navegador · confira o status de cada pedido.</p><div id="orders-results" aria-live="polite">'+results()+'</div></div></section>'}
function update(){const box=document.querySelector('#orders-results');if(box)box.innerHTML=results()}
document.addEventListener('input',e=>{if(e.target.id==='orders-search'){query=e.target.value;update()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-order-filter]');if(!b)return;active=b.dataset.orderFilter;document.querySelectorAll('[data-order-filter]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));update()});
window.ordersPage={page,refresh:update};
})();